#include "postquantiquecoin/storage/BlockStorage.h"
#include "postquantiquecoin/core/Serialization.h"
#include "postquantiquecoin/crypto/Hashing.h"
#include "postquantiquecoin/storage/FileStorage.h"
#include <algorithm>
namespace pqc { BlockStorage::BlockStorage(std::filesystem::path d,uint8_t n):dir_(std::move(d)),networkId_(n){ std::filesystem::create_directories(dir_);} std::filesystem::path BlockStorage::PathForHeight(uint64_t h) const{return dir_/(std::to_string(h)+".blk2");} Result<void> BlockStorage::WriteBlockAtomic(const Block& b){ auto payload=b.Serialize(); Serializer s; s.String("PQCBLOCKSTORE"); s.U32(2); s.U32(networkId_); s.U64(b.header.height); s.String(b.header.GetBlockId()); s.Bytes(payload); auto chk=Hashing::Sha3_256(payload); s.Bytes(std::vector<uint8_t>(chk.begin(),chk.end())); return FileStorage::AtomicWrite(PathForHeight(b.header.height),s.Data());} Result<Block> BlockStorage::ReadBlock(const std::filesystem::path& p) const{ auto bytes=FileStorage::ReadFile(p); if(bytes.IsErr()) return Result<Block>::Err(bytes.Error()); Deserializer d(bytes.Value()); auto m=d.String(); if(m.IsErr()||m.Value()!="PQCBLOCKSTORE") return Result<Block>::Err("bad block record magic"); auto v=d.U32(); if(v.IsErr()||v.Value()!=2) return Result<Block>::Err("bad block record version"); auto n=d.U32(); if(n.IsErr()||n.Value()!=networkId_) return Result<Block>::Err("wrong block record network"); auto h=d.U64(); if(h.IsErr()) return Result<Block>::Err(h.Error()); auto id=d.String(); if(id.IsErr()) return Result<Block>::Err(id.Error()); auto payload=d.Bytes(); if(payload.IsErr()) return Result<Block>::Err(payload.Error()); auto chk=d.Bytes(); if(chk.IsErr()) return Result<Block>::Err(chk.Error()); auto c=Hashing::Sha3_256(payload.Value()); if(chk.Value().size()!=32||!std::equal(c.begin(),c.end(),chk.Value().begin())) return Result<Block>::Err("block payload checksum mismatch"); auto b=Block::Deserialize(payload.Value()); if(b.IsErr()) return b; if(b.Value().header.height!=h.Value()||b.Value().header.GetBlockId()!=id.Value()) return Result<Block>::Err("block record identity mismatch"); return b;} Result<Block> BlockStorage::ReadBlockByHeight(uint64_t h) const{return ReadBlock(PathForHeight(h));} Result<Block> BlockStorage::ReadBlockByHash(const std::string& hash) const{ for(const auto& p:ListStoredBlocks()){ auto b=ReadBlock(p); if(b.IsOk()&&b.Value().header.GetBlockId()==hash) return b;} return Result<Block>::Err("block not found");} Result<void> BlockStorage::VerifyBlockRecord(const std::filesystem::path& p) const{ auto b=ReadBlock(p); return b.IsOk()?Result<void>::Ok():Result<void>::Err(b.Error());} std::vector<std::filesystem::path> BlockStorage::ListStoredBlocks() const{ std::vector<std::filesystem::path> v; if(!std::filesystem::exists(dir_)) return v; for(auto& e:std::filesystem::directory_iterator(dir_)) if(e.path().extension()==".blk2") v.push_back(e.path()); std::sort(v.begin(),v.end()); return v;} Result<void> BlockStorage::RepairIndexFromDisk(){ for(const auto& p:ListStoredBlocks()){ auto v=VerifyBlockRecord(p); if(v.IsErr()) return v;} return Result<void>::Ok();} }
